// 没有待确认交接、也没有子样的查询结果：子样列表为空、历史保留、
// 待确认详情为空；调用方自行添入的内容不能创建对应记录。
func TestGetSampleEmptyResultStaysEmpty(t *testing.T) {
	s, _ := fixedStore(t)
	mustRegister(t, s, "S", "2.500", "张三", "实验室A")

