	if pt == nil || pt.TransferID != "TR-1" || pt.ToHolder != "李四" ||
		pt.ToLocation != "实验室B" || !pt.HandedOverAt.Equal(hAt) ||
		pt.Qty != "6.000" || pt.Confirmed {
		t.Fatalf("待确认交接详情基线错误: %+v", pt)
