	v1.History[0].Holder = "王五"
	v1.History[0].Detail = "篡改"
	v1.History = append(v1.History[:1], History{Kind: "transfer-in", Holder: "王五"})

	// 另一份已经取得的结果应保持原样。
	if v2.Remaining != "6.000" || v2.Holder != "张三" || v2.Location != "实验室A" {
